function feedTasks(rows){return rows.length?rows.map(t=>'<div class="feed-row"><div><strong>'+esc(t.title)+'</strong><small>'+esc(t.status)+' · '+esc(t.priority)+'</small></div><span>'+esc(String(t.createdAt).slice(0,10))+'</span></div>').join(''):'<p class="muted">No tasks yet.</p>'}
