async function ticketDetail(id){if(!id){await openPage('tickets');return}const visible=await TM.Tickets.visible(current.id);if(!visible.some(x=>x.id===id)){currentTicketId=null;sessionStorage.removeItem('tm-ticket-id');await openPage('tickets');return}const t=await TM.Tickets.state(id),history=await TM.Tickets.timeline(id),comments=await TM.Tickets.comments(id),users=[];for(const u of (await TM.Store.list('user')).filter(x=>!x._corrupt))users.push(await TM.Identity.userState(u.id));const uname=x=>users.find(u=>u.id===x)?.displayName||users.find(u=>u.id===x)?.username||'Unknown';$('#content').innerHTML='<div class="top"><div><button id="back-tickets" class="secondary">← Tickets</button> <button id="report-ticket" class="secondary">Generate PDF Report</button><h1>'+esc(t.title)+'</h1><p class="muted">'+esc(t.description||'No description')+'</p></div><span class="status-chip">'+esc(t.status)+'</span></div><div class="card timeline-card"><div class="top"><h2>Ticket Timeline</h2><span class="muted">'+history.length+' events</span></div><div class="timeline">'+history.map(e=>'<div class="timeline-item"><span class="timeline-dot"></span><div><strong>'+esc(e.label)+'</strong><small>'+esc(uname(e.actorId))+' · '+esc(String(e.date).slice(0,16).replace('T',' '))+'</small></div></div>').join('')+'</div></div><div class="card"><h2>Comments</h2><div class="comment-list">'+(comments.length?comments.map(x=>'<article class="comment"><div class="comment-meta">'+esc(uname(x.authorId))+' · '+esc(String(x.createdAt).slice(0,16).replace('T',' '))+'</div><div class="comment-body">'+x.html+'</div></article>').join(''):'<p class="muted">No comments yet.</p>')+'</div>'+richEditor('ticket-comment')+'<button id="add-ticket-comment">Add Comment</button></div>';$('#report-ticket').onclick=()=>generateReport('ticket',id);$('#back-tickets').onclick=async()=>{currentTicketId=null;sessionStorage.removeItem('tm-ticket-id');await openPage('tickets')};bindEditor('ticket-comment');$('#add-ticket-comment').onclick=async()=>{try{const html=safeRich($('#ticket-comment').innerHTML);await TM.Tickets.addComment(current.id,id,html);msg('Comment added.',true);await ticketDetail(id)}catch(x){msg(x.message)}}}
async function generateReport(kind,id){const w=window.open('','_blank');if(!w){msg('Allow pop-ups to generate the PDF report.');return}w.document.write('<title>Preparing report…</title><p style="font-family:sans-serif;padding:24px">Preparing report…</p>');try{const users=[],groups=[];for(const x of (await TM.Store.list('user')).filter(x=>!x._corrupt))users.push(await TM.Identity.userState(x.id));for(const x of (await TM.Store.list('group')).filter(x=>!x._corrupt))groups.push(await TM.Identity.groupState(x.id));const uname=x=>users.find(u=>u.id===x)?.displayName||users.find(u=>u.id===x)?.username||'—',gname=x=>groups.find(g=>g.id===x)?.name||'—',dt=x=>x?String(x).replace('T',' ').replace('Z','').slice(0,19):'—',settings=await TM.Settings.get();let title='',recordId=id,status='—',creator='—',created='—',assignedGroups=[],assignedMembers=[],description='',timeline=[],comments=[],extra=[];if(kind==='project'){const p=await TM.Projects.state(id),pg=await TM.Projects.groups(id),tasks=await TM.Tasks.list(id),pm=(await TM.Store.list('projectMember')).filter(x=>!x._corrupt&&x.projectId===id&&x.enabled!==false);title=p.name;status=p.status||'Active';creator=uname(p.ownerId);created=dt(p.createdAt);description=p.description||'';assignedGroups=pg.map(x=>gname(x.groupId));assignedMembers=[...new Set([...pm.map(x=>uname(x.userId)),...tasks.filter(x=>x.assigneeId).map(x=>uname(x.assigneeId))])];timeline=await TM.Projects.timeline(id);comments=await TM.Projects.comments(id);extra=[['Start date',p.startDate||'—'],['Target date',p.targetDate||'—'],['Project tasks',String(tasks.length)]]}else if(kind==='task'){const t=await TM.Tasks.state(id);title=t.title;status=t.status;creator=uname(t.creatorId);created=dt(t.createdAt);description=t.description||'';assignedGroups=[gname(t.responsibleGroupId)];assignedMembers=t.assigneeId?[uname(t.assigneeId)]:[];timeline=await TM.Tasks.timeline(id);comments=await TM.Tasks.comments(id);extra=[['Priority',t.priority||'—'],['Due date',t.dueAt||'—'],['Project',t.projectId||'Standalone task']]}else if(kind==='ticket'){const t=await TM.Tickets.state(id);title=t.title;status=t.status;creator=uname(t.requesterId);created=dt(t.createdAt);description=t.description||'';assignedGroups=[gname(t.responsibleGroupId)];assignedMembers=t.assigneeId?[uname(t.assigneeId)]:[];timeline=await TM.Tickets.timeline(id);comments=await TM.Tickets.comments(id);extra=[['Priority',t.priority||'—'],['Resolution',t.resolution||'—']]}else{const a=await TM.Actions.get(id);title=a.actionType;status='Recorded';creator=uname(a.actorId);created=dt(a.createdAt);description=a.details||'';assignedGroups=[a.groupId?gname(a.groupId):'Organization-wide'];assignedMembers=[uname(a.actorId)];timeline=[{date:a.createdAt,label:'Action recorded',actorId:a.actorId}];comments=await TM.Actions.comments(id);extra=[['Target',a.target],['Reason',a.reason],['Impact / Scope',a.impact||'—'],['Evidence / Reference',a.evidence||'—']]}const E=v=>esc(v),rich=x=>safeRich(x),label=kind[0].toUpperCase()+kind.slice(1),meta=[['Record type',label],['Record ID',recordId],['Name / Title',title],['Created by',creator],['Created at',created],['Current status',status],['Assigned group(s)',assignedGroups.join(', ')||'—'],['Assigned member(s)',assignedMembers.join(', ')||'—'],...extra];const html='<!doctype html><html><head><meta charset="utf-8"><title>'+E(label+' - '+title)+'</title><style>@page{size:A4;margin:16mm}*{box-sizing:border-box}body{font:12px Arial,sans-serif;color:#111;margin:0}.head{border-bottom:3px solid #222;padding-bottom:12px;margin-bottom:18px}.head h1{font-size:24px;margin:0 0 5px}.sub{color:#555}.toolbar{position:fixed;right:20px;top:20px}.toolbar button{padding:9px 14px}table{width:100%;border-collapse:collapse;margin:12px 0 20px}th,td{border:1px solid #ccc;padding:8px;text-align:left;vertical-align:top}th{width:28%;background:#f2f2f2}h2{font-size:16px;border-bottom:1px solid #bbb;padding-bottom:5px;margin-top:22px}.timeline,.comments{list-style:none;padding:0}.timeline li,.comment{border-left:3px solid #777;padding:6px 10px;margin:8px 0;break-inside:avoid}.when{color:#666;font-size:10px}.comment{border:1px solid #ccc;border-left:3px solid #777}.desc{white-space:pre-wrap}.footer{margin-top:28px;border-top:1px solid #ccc;padding-top:8px;color:#666;font-size:10px}@media print{.toolbar{display:none}body{font-size:11px}}</style></head><body><div class="toolbar"><button onclick="window.print()">Print / Save as PDF</button></div><div class="head"><h1>'+E(settings.systemName||'Task Management')+'</h1><div class="sub">'+E(label)+' Report · Generated '+E(dt(new Date().toISOString()))+'</div></div><h2>'+E(title)+'</h2><table>'+meta.map(x=>'<tr><th>'+E(x[0])+'</th><td>'+E(x[1])+'</td></tr>').join('')+'</table><h2>Description / Details</h2><div class="desc">'+E(description||'—')+'</div><h2>Timeline</h2><ul class="timeline">'+(timeline.length?timeline.map(x=>'<li><strong>'+E(x.label)+'</strong><div class="when">'+E(uname(x.actorId))+' · '+E(dt(x.date))+'</div></li>').join(''):'<li>No timeline events.</li>')+'</ul><h2>Comments</h2><div class="comments">'+(comments.length?comments.map(x=>'<div class="comment"><div class="when">'+E(uname(x.authorId))+' · '+E(dt(x.createdAt))+'</div><div>'+rich(x.html)+'</div></div>').join(''):'<p>No comments.</p>')+'</div><div class="footer">Generated from '+E(settings.systemName||'Task Management')+'. This report reflects the record state at generation time.</div></body></html>';w.document.open();w.document.write(html);w.document.close();w.focus();setTimeout(()=>w.print(),250)}catch(e){w.document.body.innerHTML='<p style="font-family:sans-serif;padding:24px">Report generation failed: '+esc(e.message)+'</p>';msg('Report generation failed: '+e.message)}}
function safeRich(html){const tpl=document.createElement('template');tpl.innerHTML=String(html||'');const allowed=new Set(['B','STRONG','I','EM','FONT','BR','DIV','P','SPAN']);for(const el of [...tpl.content.querySelectorAll('*')]){if(!allowed.has(el.tagName)){el.replaceWith(...el.childNodes);continue}for(const a of [...el.attributes]){const n=a.name.toLowerCase();if(n==='color'&&el.tagName==='FONT'&&(/^#[0-9a-f]{6}$/i.test(a.value)||/^[a-z]{1,20}$/i.test(a.value)))continue;if(n==='size'&&el.tagName==='FONT'&&/^[1-7]$/.test(a.value))continue;if(n==='style'){const keep=[];for(const d of a.value.split(';')){const p=d.indexOf(':');if(p<0)continue;const key=d.slice(0,p).trim().toLowerCase(),val=d.slice(p+1).trim();if(key==='color'&&/^(#[0-9a-f]{3,8}|[a-z]{1,20})$/i.test(val))keep.push('color:'+val);if(key==='font-size'&&/^(?:[8-9]|[1-6][0-9]|7[0-2])px$/i.test(val))keep.push('font-size:'+val)}if(keep.length){el.setAttribute('style',keep.join(';'));continue}}el.removeAttribute(a.name)}}return tpl.innerHTML}
function richEditor(id){return '<div class="rich-editor"><div class="editor-toolbar"><button type="button" data-cmd="bold"><b>B</b></button><button type="button" data-cmd="italic"><i>I</i></button><label>Color <input type="color" data-color value="#ffffff"></label><label>Size <select data-size><option value="2">Small</option><option value="3" selected>Normal</option><option value="4">Large</option><option value="5">X-Large</option></select></label></div><div id="'+id+'" class="editor-area" contenteditable="true"></div></div>'}
function bindEditor(id){const e=$('#'+id),bar=e.closest('.rich-editor').querySelector('.editor-toolbar');bar.querySelectorAll('[data-cmd]').forEach(b=>b.onclick=()=>{e.focus();document.execCommand(b.dataset.cmd,false,null)});bar.querySelector('[data-color]').oninput=x=>{e.focus();document.execCommand('foreColor',false,x.target.value)};bar.querySelector('[data-size]').onchange=x=>{e.focus();document.execCommand('fontSize',false,x.target.value)}}
